export interface DocumentCandidate {
  readonly name: string;
  readonly mediaType: string;
  readonly bytes: readonly number[];
}

interface DocumentPreview {
  readonly name: string;
  readonly mediaType: string;
  readonly bytes: readonly number[];
}

export interface PreviewSnapshot {
  readonly preview?: DocumentPreview;
  readonly visible: boolean;
  readonly error?: string;
}

export class DocumentPreviewController {
  private preview: DocumentPreview | undefined;
  private visible = false;
  private error: string | undefined;

  select(candidate: DocumentCandidate): boolean {
    const validBytes = Array.isArray(candidate.bytes) &&
      candidate.bytes.length > 0 &&
      candidate.bytes.every(value => Number.isInteger(value) && value >= 0 && value <= 255);

    if (!candidate.name.trim() || !candidate.mediaType.startsWith('text/') || !validBytes) {
      this.preview = undefined;
      this.visible = false;
      this.error = 'Invalid document candidate';
      return false;
    }

    this.preview = {
      name: candidate.name.trim(),
      mediaType: candidate.mediaType,
      bytes: candidate.bytes,
    };
    this.visible = true;
    this.error = undefined;
    return true;
  }

  toggle(): void {
    if (this.preview !== undefined) this.visible = !this.visible;
  }

  clear(): void {
    this.preview = undefined;
    this.visible = false;
    this.error = undefined;
  }

  snapshot(): PreviewSnapshot {
    return {
      preview: this.preview === undefined
        ? undefined
        : {
            name: this.preview.name,
            mediaType: this.preview.mediaType,
            bytes: [...this.preview.bytes],
          },
      visible: this.visible,
      error: this.error,
    };
  }
}

