import { DocumentPreviewController } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

const controller = new DocumentPreviewController();
let snapshot = controller.snapshot();
assert(snapshot.visible === false, 'a new controller should be hidden');
assert(snapshot.preview === undefined, 'a new controller should have no preview');
assert(snapshot.error === undefined, 'a new controller should have no error');

const bytes = [0, 127, 255];
const candidate = { name: '  notes.txt  ', mediaType: 'text/plain', bytes };
assert(controller.select(candidate) === true, 'a valid text candidate should be selected');
bytes[0] = 99;
candidate.name = 'changed.txt';

snapshot = controller.snapshot();
assert(snapshot.visible === true, 'valid selection should be visible');
assert(snapshot.error === undefined, 'valid selection should clear the error');
assert(snapshot.preview !== undefined, 'valid selection should create a preview');
assert(snapshot.preview!.name === 'notes.txt', 'the selected name should be trimmed and snapshotted');
assert(snapshot.preview!.mediaType === 'text/plain', 'the media type should be retained');
assert(snapshot.preview!.bytes.join(',') === '0,127,255', 'candidate byte mutations must not affect the preview');

const first = controller.snapshot();
const second = controller.snapshot();
assert(first !== second, 'snapshot should return a fresh object');
assert(first.preview !== second.preview, 'snapshot previews should be fresh objects');
assert(first.preview!.bytes !== second.preview!.bytes, 'snapshot bytes should be fresh arrays');
(first.preview!.bytes as number[])[1] = 8;
(first.preview as { name: string }).name = 'damaged';
assert(controller.snapshot().preview!.bytes.join(',') === '0,127,255', 'snapshot mutation must not affect stored bytes');
assert(controller.snapshot().preview!.name === 'notes.txt', 'snapshot mutation must not affect stored metadata');

controller.toggle();
assert(controller.snapshot().visible === false, 'toggle should hide an existing preview');
controller.toggle();
assert(controller.snapshot().visible === true, 'toggle should show an existing preview');

const invalidCandidates: unknown[] = [
  { name: '', mediaType: 'text/plain', bytes: [1] },
  { name: '   ', mediaType: 'text/plain', bytes: [1] },
  { name: 'a.bin', mediaType: 'application/octet-stream', bytes: [1] },
  { name: 'a.txt', mediaType: 'TEXT/plain', bytes: [1] },
  { name: 'a.txt', mediaType: 'text/plain', bytes: [] },
  { name: 'a.txt', mediaType: 'text/plain', bytes: [-1] },
  { name: 'a.txt', mediaType: 'text/plain', bytes: [256] },
  { name: 'a.txt', mediaType: 'text/plain', bytes: [1.5] },
  { name: 'a.txt', mediaType: 'text/plain', bytes: [Number.NaN] },
];
for (const invalid of invalidCandidates) {
  assert(controller.select(invalid as never) === false, 'invalid candidates should be rejected');
  const invalidSnapshot = controller.snapshot();
  assert(invalidSnapshot.preview === undefined, 'invalid selection should clear the preview');
  assert(invalidSnapshot.visible === false, 'invalid selection should hide the preview');
  assert(typeof invalidSnapshot.error === 'string' && invalidSnapshot.error.length > 0, 'invalid selection should set an error');
  controller.toggle();
  assert(controller.snapshot().visible === false, 'toggle should do nothing without a preview');
}

controller.clear();
snapshot = controller.snapshot();
assert(snapshot.preview === undefined && snapshot.visible === false && snapshot.error === undefined, 'clear should reset preview, visibility, and error');

